		jwtDecoder.setJwtValidator(
				new org.springframework.security.oauth2.core.DelegatingOAuth2TokenValidator(
						new org.springframework.security.oauth2.jwt.JwtTimestampValidator(),
						new JwtAudienceValidator()
				)
		);

		return jwtDecoder;
	}

	@Bean
