                    .locationLat(row.getBigDecimal("location_lat"))
                    .locationLon(row.getBigDecimal("location_lon"))
                    .createdAt(row.getTimestamp("created_at") != null ? row.getTimestamp("created_at").toLocalDateTime() : null)
