        try {
            return jdbcTemplate.query(
                    "SELECT * FROM skillspot.benutzer;",
                    benutzerRowMapper
            );
        } catch (DataAccessException e) {
            log.error("Failed to load users: {}", e.getMessage());
            return Collections.emptyList();
        }
    }

    public Optional<BenutzerEntity> findByAuth0Sub(String sub) {
        try {
            List<BenutzerEntity> users = jdbcTemplate.query(
                    "SELECT * FROM skillspot.benutzer WHERE auth0_sub = ?;",
                    benutzerRowMapper,
                    sub
            );
            return users.stream().findFirst();
        } catch (DataAccessException e) {
            log.error("Database error in findByAuth0Sub (possibly missing columns): {}", e.getMessage());
            return Optional.empty();
        }
    }

    public void upsertByAuth0Sub(String sub, CompleteProfileRequest req) {
        String sql = """
                INSERT INTO skillspot.benutzer (auth0_sub, display_name, rolle, location_lat, location_lon, updated_at)
                VALUES (?, ?, ?, ?, ?, now())
                ON CONFLICT (auth0_sub) DO UPDATE SET
                    display_name = EXCLUDED.display_name,
                    rolle = EXCLUDED.rolle,
                    location_lat = EXCLUDED.location_lat,
                    location_lon = EXCLUDED.location_lon,
                    updated_at = now();
                """;
        try {
            jdbcTemplate.update(sql, sub, req.getDisplayName(), req.getRolle(), req.getLocationLat(), req.getLocationLon());
